func TestGetShadowBranchNameForCommit(t *testing.T) {
	// Hash of empty worktreeID (main worktree) is "e3b0c4"
	mainWorktreeHash := "e3b0c4"

	tests := []struct {
		name       string
		baseCommit string
		worktreeID string
		want       string
	}{
