// avoiding redundant shadow branch resolution and condensation attempts.
func TestPostCommit_FullyCondensedEndedSession_SkippedOnNextCommit(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

